glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec4 a_color;
out vec4 v_color;
#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif
void main () {
  vec4 pos = vec4(a_position, 1);
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif
  v_color = a_color;
  gl_Position = pos;
}

glsl3.frag:
precision highp float;
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
      if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
      if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 v_color;
#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
#endif
uniform Properties{
  float f_weight;
  float v_insX;
  float v_insY;
  float i_times;
};
void main () {
  vec4 o = vec4(1, 1, 1, 1);
  const float i_num = 50.0;
  vec2 v_ins = vec2(v_insX,v_insY);
  vec2 v = v_uv0;
  v.x=v.x-i_times*v_insX/2.0;
  v.y=v.y-i_times*v_insY/2.0;
  o = texture2D(texture, v) * f_weight;
  for (float s = 1.0; s <= i_num; s += 1.0)
  {
      if(s<i_times)
      {
        v += v_ins;
        o += texture2D(texture, v) * f_weight;
      }
  }
  o *= v_color;
  ALPHA_TEST(o);
  gl_FragColor = o;
}

